import { lazy } from 'react';
import { ExchangeFunnelProps } from '~/widgets/exchange-funnel-router/ui/exchange-funnel-router';
import { usePaymentFunnel } from '~/widgets/exchange-payment-funnel/lib/use-payment-funnel';
import { FunnelStep } from '~/widgets/exchange-payment-funnel/model/enums';
import {
  금액입력Context,
  금액확인Context,
  완료Context,
  처리중Context,
} from '~/widgets/exchange-payment-funnel/model/schemas';
import { BaseExchangeContext } from '~/entities/exchange';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';
import { InputAmountPage } from './input-amount-page';

const InputConfirmPage = lazy(() =>
  import('./input-confirm-page').then((module) => ({ default: module.InputConfirmPage })),
);
const ProcessPage = lazy(() => import('./process-page').then((module) => ({ default: module.ProcessPage })));
const CompletePage = lazy(() => import('./complete-page').then((module) => ({ default: module.CompletePage })));

type PaymentConfig = BaseExchangeContext & {
  txCd?: string;
};

export const PaymentFunnel = ({
  config,
  onProcessingStart,
  onProcessingSuccess,
  onProcessingError,
  onComplete,
}: ExchangeFunnelProps) => {
  const paymentConfig = config as PaymentConfig;

  const { funnel } = usePaymentFunnel({
    step:
      paymentConfig?.trnscTypeCd === TrnscTypeCd.결제 && paymentConfig?.txCd
        ? FunnelStep.금액확인
        : FunnelStep.금액입력,
    context: {
      ...config,
    },
  });

  return (
    <funnel.Render
      금액입력={({ context, history }) => (
        <InputAmountPage
          context={context as 금액입력Context}
          onNext={(onNextParams) => {
            onProcessingStart?.();
            history.push(FunnelStep.금액확인, { ...context, ...onNextParams });
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
      금액확인={({ context, history }) => (
        <InputConfirmPage
          context={context as 금액확인Context}
          onNext={(onNextParams) => {
            onProcessingStart?.();
            history.push(FunnelStep.처리중, { ...context, ...onNextParams });
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
      처리중={({ context, history }) => (
        <ProcessPage
          context={context as 처리중Context}
          onNext={({ trnscId, reqAliasNm }) => {
            // onProcessingSuccess?.(result);
            history.push(FunnelStep.완료, {
              ...context,
              trnscId,
              reqAliasNm,
            });
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
      완료={({ context }) => (
        <CompletePage
          context={context as 완료Context}
          onNext={({ redirectPath }) => {
            onComplete?.(redirectPath);
          }}
          onError={(error) => {
            onProcessingError?.(error);
          }}
        />
      )}
    />
  );
};
