import { z } from 'zod';
import { BaseExchangeContextSchema } from '~/entities/exchange/model/schemas';
import { CommandTypeSchema } from '~/shared/api/dtos/enums';
import { FunnelStep } from './enums';

const 결제_Schema = BaseExchangeContextSchema.extend({
  aliasNm: z.string().optional(),
  walletInsttCd: z.string().optional(),
  orderNo: z.string().optional().nullable(),
  // 바우처 정보
  vouchId: z.string().optional(),
  vouchAddres: z.string().optional(),
  vouchAmt: z.string().optional(),
  vouchNm: z.string().optional(),
  amt: z.string().optional(),
  txCd: z.string().optional(),
  placeNm: z.string().optional(),
  placeSecret: z.string().optional(),
  placeId: z.string().optional(),
  // 플래그
  isAppToApp: z.boolean().optional(),
  isQrScan: z.boolean().optional(),
  vouchBankCode: z.string().optional(),
  vouchTypeNm: z.string().optional(),
  vouchTyCd: z.string().optional(),
  insttWalletAdres: z.string().optional(),
  vouchTyNm: z.string().optional(),
  command: CommandTypeSchema.optional(),
  //QR
  mpmType: z.string().optional(),
}).partial();

export type 결제Context = z.infer<typeof 결제_Schema>;

export const 금액입력_Schema = 결제_Schema.required({
  mpmType: true,
  aliasNm: true,
  tokenId: true,
  trnscTypeCd: true,
  walletInsttCd: true,
});

export const 금액확인_Schema = 결제_Schema.required({
  tokenId: true,
  trnscTypeCd: true,
  trnscAmt: true,
  // shortBankName: true,
  placeNm: true,
});

export const 처리중_Schema = 금액확인_Schema;

export const 완료_Schema = 처리중_Schema.required({
  trnscId: true,
  redirectPath: true,
});

export type 금액입력Context = z.infer<typeof 금액입력_Schema>;
export type 금액확인Context = z.infer<typeof 금액확인_Schema>;
export type 처리중Context = z.infer<typeof 처리중_Schema>;
export type 완료Context = z.infer<typeof 완료_Schema>;

export type FunnelContextMap = {
  [FunnelStep.금액입력]: 결제Context;
  [FunnelStep.금액확인]: 결제Context;
  [FunnelStep.처리중]: 결제Context;
  [FunnelStep.완료]: 결제Context;
};
